export type ExpansionLocale = "de" | "es" | "fr" | "it";

type ExpansionMap = Record<ExpansionLocale, Record<string, string[]>>;

export function splitArticleExpansion(text: string): [string, string] {
  const sentences = text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map((sentence) => sentence.trim()).filter(Boolean) || [text];
  if (sentences.length > 1) {
    const middle = Math.ceil(sentences.length / 2);
    return [sentences.slice(0, middle).join(" "), sentences.slice(middle).join(" ")];
  }
  const words = text.split(/\s+/);
  const middle = Math.ceil(words.length / 2);
  return [words.slice(0, middle).join(" "), words.slice(middle).join(" ")];
}

